<script setup lang="ts">
import {computed,onMounted,ref} from 'vue';import TencentMap from './TencentMap.vue';import StudioPlaceCreate from './StudioPlaceCreate.vue';import {getStudio,type StudioPayload} from './content-studio-api';import {studioMapPoint} from '../../shared/studio-place-creation';import type {MapPlace} from '../../shared/coordinates';
const payload=ref<StudioPayload|null>(null),selected=ref(''),creating=ref(false),point=ref<{latitude:number;longitude:number}|undefined>();onMounted(async()=>payload.value=await getStudio());
const items=computed<MapPlace[]>(()=>Object.values(payload.value?.document.places||{}).filter(p=>!p.archivedAt&&!p.coordinateMissing).map(p=>({code:p.id,name:p.name.zh,...studioMapPoint(p.coordinates),public_level:'P1',current_status:p.publicStatus,map_display_role:'pin',parent_code:null,ancestor_codes:[],coordinate_id:'studio',draft:!(payload.value?.publishedPlaceIds||[]).includes(p.id),updated_at:payload.value?.updatedAt||'',category_name:p.category,region:p.region.zh,has_pending:false})));
</script>
<template><div class="workspace-page studio-page"><div class="workspace-title"><div><p class="kicker">地图</p><h1>地图可视化维护</h1><p>点击点位打开地点。地图名称与优先级在地点编辑页维护；坐标修改走安全确认流程。</p></div><button class="primary-action" @click="point=undefined;creating=true">＋ 新增地点</button></div><p class="map-draft-legend">绿色：已公开地点 · 橙色：草稿地点。此页显示本地草稿，新增点不进入公网地图。</p><StudioPlaceCreate v-if="creating&&payload" :payload="payload" :initial-point="point" @cancel="creating=false" @created="payload.document=$event.document;payload.draftRevision=$event.draftRevision;selected=$event.id;creating=false"/><TencentMap :items="items" @select="selected=$event"/><details><summary>点击地图选位置后新建</summary><TencentMap pick @pick="point=$event;creating=true"/></details><div v-if="selected" class="map-selected-card"><strong>{{payload?.document.places[selected]?.name.zh}}</strong><span>{{selected}} · {{payload?.publishedPlaceIds?.includes(selected)?'已公开地点（本地草稿）':'草稿地点'}}</span><RouterLink class="button primary-action" :to="`/studio/places/${selected}`">编辑地点内容</RouterLink><RouterLink class="button quiet" :to="`/studio/places/${selected}?preview=1`">详情预览</RouterLink></div></div></template>
